appearances.css:
*{letter-spacing:0}
.app{padding:6px;border-radius:4px;font-size:9px}
.row{gap:4px;margin:0 0 4px}
.row:first-of-type{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));align-items:end}
.row .control{border:0;padding:0;gap:1px;border-radius:0}
.control span{font-size:7px;line-height:1.1}
select,button{font-size:9px;padding:2px 3px;border-radius:3px;min-width:0;width:100%}
.row:nth-of-type(2){flex-wrap:nowrap}
.row:nth-of-type(2) button{width:auto;flex:1 1 auto;padding:2px 4px}
.row:nth-of-type(2) .control{flex:0 0 52px}
.row:nth-of-type(2){align-items:center}
h3{font-size:8px;letter-spacing:.14em;text-transform:uppercase;margin:5px 0 2px}
.grid{grid-template-columns:repeat(auto-fit,minmax(52px,1fr));gap:3px 0;border:1px solid var(--line,#344953);border-radius:3px;padding:4px 3px}
.grid .control,.row .control:has(.kn){border:0;padding:0;border-radius:0;display:grid;grid-template-columns:minmax(0,1fr);justify-items:center;align-items:start;gap:0}
.control:has(.kn)>span:not(.kn){order:3;font-size:7px;line-height:1.1;text-align:center;max-width:100%}
.control:has(.kn) output{order:2;font-size:8px;line-height:1.1;text-align:center}
.control .kn{order:1!important;width:24px!important;height:24px!important;justify-self:center!important}
.control .kn svg{width:100%;height:100%}
canvas{height:30px!important;border-radius:3px}
p{margin:4px 0 0;font-size:8px}
